SELECT hostname name,ip
FROM traffic_abnormal_machine
WHERE nmsServer_Id = #{nmsServiceId};


SELECT REDIRECT_NUM ,MONITOR_NUM,REPLACE_NUM
FROM pxy_total_report
    WHERE REPORT_TIME >= #{start}
    AND REPORT_TIME < #{end}


SELECT max(RECV_TIME)
FROM traffic_netflow_port_info
  WHERE RECV_TIME < #{end}
